#include <cstdio>
#include <vector>

int main() {
    std::vector<std::vector<int>> gray(3, std::vector<int>(3));
    for (int row = 0; row < 3; row++) {
        for (int col = 0; col < 3; col++) {
            if (std::scanf("%d", &gray[row][col]) != 1) return 1;
            if (gray[row][col] < 0 || gray[row][col] > 255) return 1;
        }
    }
    int threshold = 0;
    if (std::scanf("%d", &threshold) != 1) return 1;
    if (threshold < 0 || threshold > 255) return 1;
    int count = 0;
    for (const auto& row : gray) {
        for (int pixel : row) {
            if (pixel >= threshold) count++;
        }
    }
    std::printf("%d\n", count);
    return 0;
}
